harness.src/edma_ctrl.sv:
`timescale 1ns/1ps

parameter ID = 4'b0000;      // Group ID for DMA regs [10:8]

module edma_ctrl #( 
  parameter AW = 32,                     // Address width
  parameter PW = (3*AW + 8)              // Packet width
)(
  input  logic          clk,             // Clock
  input  logic          nreset,          // Asynchronous reset, active low
  input  logic          dma_en,          // DMA enable
  input  logic          chainmode,       // Enable descriptor chaining
  input  logic          manualmode,      // Manual mode (non-fetch)
  input  logic          mastermode,      // Master initiator mode
  input  logic [31:0]   count,           // Transfer count: [31:16] outer, [15:0] inner
  input  logic [15:0]   curr_descr,      // Current descriptor address
  input  logic [15:0]   next_descr,      // Next descriptor address (for chaining)
  input  logic          reg_wait_in,     // Wait for register fetch to complete
  input  logic          access_in,       // Slave access trigger
  input  logic          wait_in,         // Wait input from downstream
  input  logic          sec_violation,   // Security violation detected

  output logic          fetch_access,    // Fetch enable signal
  output logic [PW-1:0] fetch_packet,    // Generated fetch EMESH packet
  output logic [3:0]    dma_state,       // Current DMA FSM state
  output logic          update,          // Update enable (based on access or master active)
  output logic          update2d,        // 2D update enable (for outer loops)
  output logic          master_active    // Master transfer active
);

  // DMA FSM states
  typedef enum logic [3:0] {
    DMA_IDLE   = 4'b0000,
    DMA_FETCH0 = 4'b0001,
    DMA_FETCH1 = 4'b0010,
    DMA_FETCH2 = 4'b0011,
    DMA_FETCH3 = 4'b0100,
    DMA_FETCH4 = 4'b0101,
    DMA_INNER  = 4'b0110,
    DMA_OUTER  = 4'b0111,
    DMA_DONE   = 4'b1000,
    DMA_ERROR  = 4'b1001
  } state_e;

  // Register addresses used during fetch
  typedef enum logic [4:0] {
    EDMA_CONFIG    = 0,
    EDMA_STRIDE    = 1,
    EDMA_COUNT     = 2,
    EDMA_SRCADDR   = 3,
    EDMA_DSTADDR   = 4,
    EDMA_SRCADDR64 = 5,
    EDMA_DSTADDR64 = 6,
    EDMA_STATUS    = 7,
    EDMA_SECBASE   = 8,
    EDMA_SECMASK   = 9
  } addr_e;

  // Internal signals
  wire [15:0]    descr;
  wire [15:0]    fetch_addr;
  wire [AW-1:0]  srcaddr_out;
  wire [4:0]     reg_addr;
  wire           incount_zero;
  wire           outcount_zero;

  // FSM: DMA state transitions
  always_ff @(posedge clk or negedge nreset) begin
    if (!nreset)
      dma_state <= DMA_IDLE;
    else if (sec_violation)
      dma_state <= DMA_ERROR;
    else begin
      case (dma_state[3:0])
        DMA_IDLE:
          casez ({dma_en, manualmode})
            2'b0? : dma_state <= DMA_IDLE;
            2'b11 : dma_state <= DMA_INNER;      // Manual immediate start
            2'b10 : dma_state <= DMA_FETCH0;     // Begin fetch sequence
          endcase

        DMA_FETCH0:
          dma_state <= reg_wait_in ? DMA_FETCH0 : DMA_FETCH1;
        DMA_FETCH1:
          dma_state <= reg_wait_in ? DMA_FETCH1 : DMA_FETCH2;
        DMA_FETCH2:
          dma_state <= reg_wait_in ? DMA_FETCH2 : DMA_FETCH3;
        DMA_FETCH3:
          dma_state <= reg_wait_in ? DMA_FETCH3 : DMA_FETCH4;
        DMA_FETCH4:
          dma_state <= reg_wait_in ? DMA_FETCH4 : DMA_INNER;

        DMA_INNER:
          casez ({update, incount_zero, outcount_zero})
            3'b0?? : dma_state <= DMA_INNER;
            3'b10? : dma_state <= DMA_INNER;
            3'b110 : dma_state <= DMA_OUTER;
            3'b111 : dma_state <= DMA_DONE;
          endcase

        DMA_OUTER:
          dma_state <= update ? DMA_INNER : DMA_OUTER;

        DMA_DONE:
          casez ({chainmode, manualmode})
            2'b0?  : dma_state <= DMA_DONE;
            2'b11  : dma_state <= DMA_IDLE;
            2'b10  : dma_state <= DMA_FETCH0;
          endcase

        DMA_ERROR:
          dma_state <= dma_en ? DMA_ERROR : DMA_IDLE;
      endcase
    end
  end

  // Master active signal is asserted during inner/outer loop when master mode is enabled
  assign master_active = mastermode && (dma_state == DMA_INNER || dma_state == DMA_OUTER);


  // Update conditions: only when wait is not asserted and access/master is active
  assign update    = !wait_in && (master_active || access_in);
  `ifndef BUG_5
    assign update2d  = update && (dma_state == DMA_OUTER);
  `else
    assign update2d  = 0;
  `endif

  // Fetch access enable based on DMA state range
  assign fetch_access = (dma_state >= DMA_FETCH0 && dma_state <= DMA_FETCH4);

  // Zero count detection for inner and outer loop
  assign incount_zero  = ~(|count[15:0]);     // Inner count
  assign outcount_zero = ~(|count[31:16]);    // Outer count

  // Descriptor selection logic
  assign descr = (dma_state == DMA_FETCH0) ? next_descr : curr_descr;

  // Fetch address generation based on FSM step
  oh_mux3 #(.DW(16)) mux3d (
    .out  (fetch_addr),
    .in0  (descr),
    .sel0 (dma_state == DMA_FETCH0),
    .in1  (descr + 16'd8),
    .sel1 (dma_state == DMA_FETCH1),
    .in2  (descr + 16'd16),
    .sel2 (dma_state == DMA_FETCH2)
  );

  // Register address selection for fetch
  oh_mux3 #(.DW(5)) mux3s (
    .out  (reg_addr),
    .in0  (EDMA_CONFIG),
    .sel0 (dma_state == DMA_FETCH0),
    .in1  (EDMA_COUNT),
    .sel1 (dma_state == DMA_FETCH1),
    .in2  (EDMA_SRCADDR),
    .sel2 (dma_state == DMA_FETCH2)
  );

  // Construct source address used in EMESH packet (includes group ID)
  assign srcaddr_out = {{(AW-11){1'b0}}, ID, reg_addr, 2'b0};

  // EMESH fetch packet construction
  emesh2packet #(.AW(AW), .PW(PW)) e2p (
    .packet_out     (fetch_packet),
    .write_out      (1'b0),                          // Read packet
    .datamode_out   (2'b11),                         // Word mode
    .ctrlmode_out   (5'b0),
    .dstaddr_out    ({{(AW-16){1'b0}}, fetch_addr}), // Destination address padded
    .data_out       ({AW{1'b0}}),                    // Unused data for read
    .srcaddr_out    (srcaddr_out)                    // Source address
  );

endmodule

harness.src/edma_dp.sv:
`timescale 1ns/1ps

module edma_dp #( 
    parameter AW = 32,                 // Address width
    parameter PW = (3*AW + 8)          // Packet width
) (
    input  logic           clk,            // Clock
    input  logic           nreset,         // Asynchronous reset, active low
    input  logic           master_active,  // Indicates master mode transfer
    input  logic           update2d,       // 2D update signal for outer loop
    input  logic [1:0]     datamode,       // Master data mode
    input  logic [4:0]     ctrlmode,       // Master control mode
    input  logic [31:0]    stride_reg,     // Stride value for 2D transfer
    input  logic [31:0]    count_reg,      // Count register
    input  logic [AW-1:0]  srcaddr_reg,    // Source address register
    input  logic [AW-1:0]  dstaddr_reg,    // Destination address register
    input  logic           access_in,      // Input access signal
    input  logic [PW-1:0]  packet_in,      // Incoming EMESH packet
    input  logic           wait_in,        // Wait input from downstream

    output logic [31:0]    count,          // Updated count
    output logic [AW-1:0]  srcaddr,        // Updated source address
    output logic [AW-1:0]  dstaddr,        // Updated destination address
    output logic           wait_out,       // Wait signal output
    output logic           access_out,     // Access signal output
    output logic [PW-1:0]  packet_out      // Outgoing EMESH packet
);

  // COUNT UPDATE
  assign count = ~nreset ? 32'd0 :
                 (update2d ? { count_reg[31:16] - 16'd1, count_reg[15:0] } :
                              (count_reg - 32'd1));

  // ADDRESS INCREMENT
  assign srcaddr = srcaddr_reg + {{(AW-16){stride_reg[15]}}, stride_reg[15:0]};
  assign dstaddr = dstaddr_reg + {{(AW-16){stride_reg[31]}}, stride_reg[31:16]};

  // Internal wires for packet conversion
  wire [4:0]      ctrlmode_out;
  wire [AW-1:0]   data_out;
  wire [1:0]      datamode_out;
  wire [AW-1:0]   dstaddr_out;
  wire [AW-1:0]   srcaddr_out;
  wire            write_out;
  wire [PW-1:0]   packet;

  // Decoded inputs from packet
  wire [4:0]      ctrlmode_in;
  wire [AW-1:0]   data_in;
  wire [1:0]      datamode_in;
  wire [AW-1:0]   dstaddr_in;
  wire [AW-1:0]   srcaddr_in;
  wire            write_in;

  // Decode incoming EMESH packet
  packet2emesh #(.AW(AW), .PW(PW)) u_p2e (
    .packet_in    (packet_in),
    .write_in     (write_in),
    .datamode_in  (datamode_in),
    .ctrlmode_in  (ctrlmode_in),
    .dstaddr_in   (dstaddr_in),
    .data_in      (data_in),
    .srcaddr_in   (srcaddr_in)
  );

  // Select fields based on master or slave mode
  assign write_out         = master_active ? 1'b0          : write_in;
  assign datamode_out      = master_active ? datamode      : datamode_in;
  assign ctrlmode_out      = master_active ? ctrlmode      : ctrlmode_in;
  `ifndef BUG_2
    assign dstaddr_out       = dstaddr;
  `else
    assign dstaddr_out       = 0;
  `endif
  assign data_out          = master_active ? {AW{1'b0}}     : data_in;
  `ifndef BUG_7
    assign srcaddr_out       = master_active ? {AW{1'b0}}     : srcaddr_in;
  `else
    assign srcaddr_out       = {AW{1'b1}} ;
  `endif
  // Encode EMESH packet
  emesh2packet #(.AW(AW), .PW(PW)) u_e2p (
    .write_out     (write_out),
    .datamode_out  (datamode_out),
    .ctrlmode_out  (ctrlmode_out),
    .dstaddr_out   (dstaddr_out),
    .data_out      (data_out),
    .srcaddr_out   (srcaddr_out),
    .packet_out    (packet)
  );

  // Drive output packet and access when not stalled
  always @(posedge clk or negedge nreset) begin
    if (!nreset) begin
      packet_out <= {PW{1'b0}};
      access_out <= 1'b0;
    end else if (~wait_in) begin
      `ifndef BUG_1
        packet_out <= packet;
      `else
        packet_out <= 0;
      `endif    
      access_out <= access_in | master_active;
    end
  end

  // Pass wait signal through
  assign wait_out = wait_in;

endmodule

harness.src/edma_regs.sv:
`timescale 1ns/1ps

module edma_regs #( 
    parameter AW = 32,                  // Address width
    parameter PW = (3*AW + 8)           // Packet width
)(
    input  logic           clk,             // Clock
    input  logic           nreset,          // Asynchronous reset
    input  logic           reg_access_in,   // Input register access valid
    input  logic [PW-1:0]  reg_packet_in,   // Register access packet input
    output logic           reg_wait_out,    // Register wait output (not used)
    output logic           reg_access_out,  // Fetch access passthrough
    output logic [PW-1:0]  reg_packet_out,  // Fetch packet passthrough

    output logic           dma_en,          // DMA enable output
    output logic           mastermode,      // Master mode output
    output logic           manualmode,      // Manual mode output (inverted)
    output logic [1:0]     datamode,        // Data mode
    output logic [4:0]     ctrlmode,        // Control mode
    output logic           chainmode,       // Chain mode enable
    output logic           irq,             // IRQ output
    output logic [15:0]    next_descr,      // Next descriptor address
    output logic [15:0]    curr_descr,      // Current descriptor address
    output logic [31:0]    stride_reg,      // Stride register
    output logic [31:0]    count_reg,       // Count register
    output logic [AW-1:0]  dstaddr_reg,     // Destination address register
    output logic [AW-1:0]  srcaddr_reg,     // Source address register
    output logic [AW-1:0]  secure_base_reg, // Secure base address register
    output logic [AW-1:0]  secure_mask_reg, // Secure mask register

    input  logic           fetch_access,    // Fetch access input
    input  logic [PW-1:0]  fetch_packet,    // Fetch packet input
    input  logic [31:0]    count,           // Count input
    input  logic [AW-1:0]  dstaddr,         // Destination address input
    input  logic [AW-1:0]  srcaddr,         // Source address input
    input  logic [3:0]     dma_state,       // DMA FSM state
    input  logic           update           // Update enable
);

  // Internal control signals for register write decoding
  wire               reg_write;
  wire               config_write;
  wire               stride_write;
  wire               count_write;
  wire               src0_write;
  wire               src1_write;
  wire               dst0_write;
  wire               dst1_write;
  wire               status_write;
  wire               secbase_write;
  wire               secmask_write;
  wire               irqmode;

  // Address decode enumeration
  typedef enum logic [4:0] {
    EDMA_CONFIG    = 0,
    EDMA_STRIDE    = 1,
    EDMA_COUNT     = 2,
    EDMA_SRCADDR   = 3,
    EDMA_DSTADDR   = 4,
    EDMA_SRCADDR64 = 5,
    EDMA_DSTADDR64 = 6,
    EDMA_STATUS    = 7,
    EDMA_SECBASE   = 8,
    EDMA_SECMASK   = 9
  } addr_e;

  // Packet decoding wires
  wire [4:0]     ctrlmode_in;
  wire [AW-1:0]  data_in;
  wire [1:0]     datamode_in;
  wire [AW-1:0]  dstaddr_in;
  wire [AW-1:0]  srcaddr_in;
  wire          write_in;

  // Decode incoming EMESH packet for register accesses
  packet2emesh #(.AW(AW), .PW(PW)) p2e (
    .packet_in    (reg_packet_in),
    .write_in     (write_in),
    .datamode_in  (datamode_in),
    .ctrlmode_in  (ctrlmode_in),
    .dstaddr_in   (dstaddr_in),
    .srcaddr_in   (srcaddr_in),
    .data_in      (data_in)
  );

  // Decode address and enable signals for write ops
  assign reg_write     = write_in & reg_access_in;
  assign config_write  = reg_write & (dstaddr_in == EDMA_CONFIG);
  assign stride_write  = reg_write & (dstaddr_in == EDMA_STRIDE);
  assign count_write   = reg_write & (dstaddr_in == EDMA_COUNT);
  assign src0_write    = reg_write & (dstaddr_in == EDMA_SRCADDR);
  assign src1_write    = reg_write & (dstaddr_in == EDMA_SRCADDR64);
  assign dst0_write    = reg_write & (dstaddr_in == EDMA_DSTADDR);
  assign dst1_write    = reg_write & (dstaddr_in == EDMA_DSTADDR64);
  assign status_write  = reg_write & (dstaddr_in == EDMA_STATUS);
  assign secbase_write = reg_write & (dstaddr_in==EDMA_SECBASE);
  assign secmask_write = reg_write & (dstaddr_in==EDMA_SECMASK);

  // Configuration and status registers
  reg [31:0] status_reg;
  reg [31:0] config_reg;
  reg [AW-1:0] secure_base_r;
  reg [AW-1:0] secure_mask_r;

  // Config register logic
  always_ff @(posedge clk or negedge nreset) begin
    if (!nreset)
      config_reg <= 0;
    else if (config_write)
      config_reg <= data_in;
  end

  `ifndef BUG_6
    assign dma_en     = config_reg[0];
  `else
    assign dma_en     = ~config_reg[0];
  `endif
  assign mastermode = config_reg[1];
  assign chainmode  = config_reg[2];
  `ifndef BUG_4
    assign manualmode = ~config_reg[3];
  `else
    assign manualmode = config_reg[3];
  `endif
  assign irqmode    = config_reg[4];          // IRQ mode bit
  assign datamode   = config_reg[6:5];        // Data mode
  assign ctrlmode   = 5'd0;                   // Defaulted
  assign next_descr = config_reg[31:16];

  // Stride register logic
  always_ff @(posedge clk or negedge nreset) begin
    if (!nreset)
      stride_reg <= 32'd0;
    else if (stride_write)
      stride_reg <= data_in;
  end

  // Count register logic
  always_ff @(posedge clk or negedge nreset) begin
    if (!nreset)
      count_reg <= 32'd0;
    else if (count_write)
      count_reg <= data_in;
    else if (update)
      count_reg <= count;
  end

  // Source address register logic
  always_ff @(posedge clk or negedge nreset) begin
    if (!nreset)
      srcaddr_reg <= {AW{1'b0}};
    else if (src0_write)
      srcaddr_reg[31:0] <= data_in;
    else if (src1_write)
      srcaddr_reg[63:32] <= data_in;
    else if (update)
      srcaddr_reg <= srcaddr;
  end

  // Destination address register logic
  always_ff @(posedge clk or negedge nreset) begin
    if (!nreset)
      dstaddr_reg <= {AW{1'b0}};
    else if (dst0_write)
      dstaddr_reg[31:0] <= data_in;
    else if (dst1_write)
      dstaddr_reg[63:32] <= data_in;
    else if (update)
      dstaddr_reg <= dstaddr;
  end

  // Status register update
  always_ff @(posedge clk or negedge nreset) begin
    if (!nreset)
      status_reg <= 32'd0;
    else if (status_write)
      status_reg <= data_in;
    else if (config_write)
      status_reg <= {next_descr, 12'd0, dma_state};
  end

  assign curr_descr = status_reg[31:16];

  // secure registers
  always @(posedge clk or negedge nreset) begin
    if (!nreset) begin
      secure_base_reg <= {(AW-1){1'b0}};
      secure_mask_reg <= {(AW-1){1'b0}};
    end 
    else if (secbase_write) 
      secure_base_reg <= data_in[AW-1:0];
    else if (secmask_write) 
      secure_mask_reg <= data_in[AW-1:0];
  end

  // Register readback (pass through fetch packet)
  assign reg_wait_out   = 1'b0;
  assign reg_access_out = fetch_access;
  assign reg_packet_out = fetch_packet;


  // IRQ output (not used, hardwired to 0)
  assign irq = 1'b0;

endmodule

harness.src/edma_sec_checker.sv:
`timescale 1ns/1ps

module edma_sec_checker #( 
    parameter AW = 32                   // Address width
)(
    input  logic [AW-1:0] srcaddr,        // Source address from DMA
    input  logic [AW-1:0] dstaddr,        // Destination address from DMA
    input  logic [AW-1:0] secure_base,    // Base address of secure region
    input  logic [AW-1:0] secure_mask,    // Secure mask bits
    input  logic          clk,            // System clock
    input  logic          nreset,         // Active-low reset
    output logic          violation       // Security violation detected
);

  // On every clock cycle, check if source or destination addresses violate secure mask
  // Violation occurs if masked difference between address and secure base is non-zero
  always_ff @(posedge clk or negedge nreset) begin
    if (!nreset)
      violation <= 1'b0;
    else
      `ifndef BUG_3
        violation <= |((srcaddr ^ secure_base) & secure_mask) ||   // Source address check
                   |((dstaddr ^ secure_base) & secure_mask);     // Destination address check
      `else
        violation <= 1'b0;
      `endif
  end

endmodule

harness.src/emesh2packet.sv:
`timescale 1ns/1ps

module emesh2packet #( 
    parameter AW = 32,                  // Address width
    parameter PW = (3*AW + 8)           // Packet width
)(
    input  logic         write_out,        // Write enable bit
    input  logic [1:0]   datamode_out,     // Data mode (byte, halfword, word)
    input  logic [4:0]   ctrlmode_out,     // Control mode (custom signaling)
    input  logic [AW-1:0] dstaddr_out,     // Destination address
    input  logic [AW-1:0] data_out,        // Data payload
    input  logic [AW-1:0] srcaddr_out,     // Source address
    output logic [PW-1:0] packet_out       // Packed EMESH packet output
);

  // Bit layout of the EMESH packet
  // [0]        - write_out
  // [2:1]      - datamode_out
  // [7:3]      - ctrlmode_out
  // [8 +: AW]        - dstaddr_out
  // [8+AW +: AW]     - data_out
  // [8+2*AW +: AW]   - srcaddr_out

  assign packet_out[0]               = write_out;
  assign packet_out[2:1]             = datamode_out;
  assign packet_out[7:3]             = ctrlmode_out;
  assign packet_out[8        +: AW]  = dstaddr_out;
  assign packet_out[8+AW     +: AW]  = data_out;
  assign packet_out[8+2*AW   +: AW]  = srcaddr_out;

endmodule

